    .map(([n, v]) => {
      const lowerName = n.toLowerCase();
      const foldedValue = foldWhitespace(v);
      return [lowerName, foldedValue] as [string, string];
    })
    .filter(([n]) => n !== "authorization")
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));

